def ensure_configuration_can_downgrade(connection):
    """Compare all configuration content, including edits to the original seeds."""
    catalog_columns = ', '.join(default_catalog()[0])
    actual_catalog = [dict(row) for row in connection.execute(sa.text(
        f'SELECT {catalog_columns} FROM exercise_catalog ORDER BY code')).mappings()]
    expected_catalog = sorted(default_catalog(), key=lambda item: item['code'])
    templates = [dict(row) for row in connection.execute(sa.text(
        'SELECT code, name, version, active FROM questionnaire_templates ORDER BY code, version')).mappings()]
    expected_templates = [dict(code='upper_limb_intake', name='Thông tin lâm sàng chi trên', version=1, active=True)]
    actual_questions = [dict(row) for row in connection.execute(sa.text(
        'SELECT q.key, q.label, q."group", q.question_type, q.required, q.display_order, q.options, '
        't.code AS template_code, t.version AS template_version '
        'FROM questionnaire_questions q JOIN questionnaire_templates t ON t.id=q.template_id '
        'ORDER BY q.display_order, q.id')).mappings()]
    expected_questions = [dict(key=key, label=label, group=group,
        question_type=kind, required=required, display_order=order, options=options,
        template_code='upper_limb_intake', template_version=1)
        for order, (key, label, group, kind, required, options) in enumerate(default_questions())]
    if actual_catalog != expected_catalog or templates != expected_templates or actual_questions != expected_questions:
        raise RuntimeError('Downgrade would discard authored workflow configuration; export and review before rollback.')


def seed_catalog_and_questionnaire():
    """Operational configuration only; never insert patients, answers or scores."""
    connection = op.get_bind()
    catalog = sa.table('exercise_catalog', sa.column('code', sa.String), sa.column('name', sa.String),
        sa.column('description', sa.Text), sa.column('instructions', sa.Text),
        sa.column('exercise_type', sa.String), sa.column('usage_mode', sa.String),
        sa.column('active', sa.Boolean), sa.column('is_default', sa.Boolean),
        sa.column('renderer', sa.String), sa.column('default_duration_seconds', sa.Integer))
    op.bulk_insert(catalog, default_catalog())
    template_id = connection.scalar(sa.text("INSERT INTO questionnaire_templates (code,name,version,active) VALUES ('upper_limb_intake','Thông tin lâm sàng chi trên',1,true) RETURNING id"))
    questions = default_questions()
    question_table = sa.table('questionnaire_questions', sa.column('template_id', sa.Integer), sa.column('key', sa.String),
        sa.column('label', sa.String), sa.column('group', sa.String), sa.column('question_type', sa.String),
        sa.column('required', sa.Boolean), sa.column('display_order', sa.Integer), sa.column('options', sa.JSON))
    op.bulk_insert(question_table, [dict(template_id=template_id, key=key, label=label, group=group,
        question_type=kind, required=required, display_order=order, options=options)
        for order, (key, label, group, kind, required, options) in enumerate(questions)])


